// Port of :core practice/PhraseDecks.kt: the say-it / listen decks (fixtures/phrases.json, generated by Kotlin).
import phrases from '../../../fixtures/phrases.json' with { type: 'json' };
import { TENSES } from './practice.ts';

export interface PhraseCard {
  id: string; english: string; spanish: string; answer: string; verb?: string; tense?: string; note?: string;
}
export type DeckId = 'questions' | 'verbs';
export type PhraseMode = 'say' | 'listen';

export const DECKS: Record<DeckId, { title: string; cards: PhraseCard[] }> = {
  questions: { title: 'Question words', cards: phrases.questions },
  verbs: { title: 'Everyday verbs', cards: phrases.verbs },
};

export const BLANK = '___';
export const filled = (c: PhraseCard) => c.spanish.replace(BLANK, c.answer);
/** "tener · present" for the verb deck; null for question words. */
export const hint = (c: PhraseCard) =>
  c.verb ? [c.verb, c.tense ? (TENSES.find((t) => t.id === c.tense)?.label ?? c.tense) : null].filter(Boolean).join(' · ') : null;

/** A practice session: the whole deck in random order. */
export function session(deck: DeckId, rand: () => number = Math.random): PhraseCard[] {
  const a = [...DECKS[deck].cards];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
